import type { UIMessage } from "ai"
import { sql } from "drizzle-orm"
import {
  boolean,
  index,
  jsonb,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core"

/**
 * The Better Auth tables, hand-written to match what the library expects
 * (core + the `username` and `admin` plugins) rather than generated by the
 * CLI - this project pushes its schema with `db:push` and keeps no migration
 * files, per AGENTS.md.
 *
 * Accounts are created by the admin (or the /install bootstrap), never by
 * self sign-up, so `email` holds a placeholder built from the username for
 * the users it is meaningless for.
 */
export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
  // username plugin
  username: text("username").unique(),
  displayUsername: text("display_username"),
  // admin plugin - `role` is "admin" or "user" (a student), and the ban
  // columns are what `banUser` writes. A ban revokes every session, which is
  // the "really disconnected" part of blocking a student.
  role: text("role").notNull().default("user"),
  banned: boolean("banned"),
  banReason: text("ban_reason"),
  banExpires: timestamp("ban_expires", { withTimezone: true }),
})

export const session = pgTable("session", {
  id: text("id").primaryKey(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  token: text("token").notNull().unique(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
  ipAddress: text("ip_address"),
  userAgent: text("user_agent"),
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  // admin plugin - set while an admin is impersonating this session.
  impersonatedBy: text("impersonated_by"),
})

export const account = pgTable("account", {
  id: text("id").primaryKey(),
  accountId: text("account_id").notNull(),
  providerId: text("provider_id").notNull(),
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  accessToken: text("access_token"),
  refreshToken: text("refresh_token"),
  idToken: text("id_token"),
  accessTokenExpiresAt: timestamp("access_token_expires_at", {
    withTimezone: true,
  }),
  refreshTokenExpiresAt: timestamp("refresh_token_expires_at", {
    withTimezone: true,
  }),
  scope: text("scope"),
  // The scrypt hash of the password, for credential accounts.
  password: text("password"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
})

export const verification = pgTable("verification", {
  id: text("id").primaryKey(),
  identifier: text("identifier").notNull(),
  value: text("value").notNull(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .default(sql`now()`),
})

export const games = pgTable(
  "games",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Better Auth user id (`user.id`), not a foreign key - same convention the
    // org column used, kept because a plain indexed column is all the scoped
    // queries need and it matches how `authorizeGame` reads it.
    userId: text("user_id").notNull(),
    title: text("title").notNull(),
    // The game's chat thread, in the `useChat` UI message format. One game has
    // exactly one thread, so it is stored inline rather than in its own table.
    messages: jsonb("messages")
      .$type<UIMessage[]>()
      .notNull()
      .default(sql`'[]'::jsonb`),
    // Trigger.dev chat session state for the thread above, written by the
    // agent's `onTurnComplete` in the same statement as the messages. The
    // cursor is what a reloading browser resumes an interrupted turn from, so
    // it must never be written ahead of the messages it points past.
    chatAccessToken: text("chat_access_token"),
    chatLastEventId: text("chat_last_event_id"),
    // The Daytona sandbox the game is built in, created on the thread's first
    // turn. Null until then, and for games created before sandboxes existed.
    sandboxId: text("sandbox_id"),
    // Soft delete: the row and its whole message thread survive deletion (a
    // school keeps its records), while everything outside the database - the
    // Trigger.dev chat session, the Daytona sandbox - really goes away.
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    // Who owned this game, written down when their account is removed and the
    // live user row disappears. Null while the owner still exists.
    ownerSnapshot: text("owner_snapshot"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .default(sql`now()`),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .default(sql`now()`)
      .$onUpdate(() => new Date()),
  },
  (table) => [
    // Games are always read scoped to a user, usually newest first. The
    // leading user_id also serves plain `where user_id = ?` lookups.
    index("games_user_id_created_at_idx").on(
      table.userId,
      table.createdAt.desc()
    ),
  ]
)

/**
 * The activity journal: one row per event worth keeping a record of - games
 * created, renamed or deleted, turns played, accounts created, blocked,
 * unblocked, reset or removed.
 *
 * `actorLabel` is denormalized on purpose: the trace must outlive the account
 * it names, the same way a game's owner snapshot does.
 */
export const auditLog = pgTable(
  "audit_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .default(sql`now()`),
    // Who did it. Null for events with no signed-in actor (the worker).
    actorId: text("actor_id"),
    actorLabel: text("actor_label").notNull(),
    // One of the ACTIONS keys in `@/lib/audit`.
    action: text("action").notNull(),
    // "game" or "user", with the row's id.
    targetType: text("target_type"),
    targetId: text("target_id"),
    // A short human-readable line: the game title, the username, the message
    // count. Never the message content itself - that lives on the game row.
    detail: text("detail"),
  },
  (table) => [index("audit_log_created_at_idx").on(table.createdAt.desc())]
)

export type AuditLogEntry = typeof auditLog.$inferSelect
export type NewAuditLogEntry = typeof auditLog.$inferInsert

export type Game = typeof games.$inferSelect
export type NewGame = typeof games.$inferInsert

export type User = typeof user.$inferSelect
export type NewUser = typeof user.$inferInsert

export type Session = typeof session.$inferSelect
export type NewSession = typeof session.$inferInsert

export type Account = typeof account.$inferSelect
export type NewAccount = typeof account.$inferInsert

export type Verification = typeof verification.$inferSelect
export type NewVerification = typeof verification.$inferInsert
